using UnityEngine; using PersiaWar.Unity2D5D; namespace PersiaWar.Unity2D5D.UI.Loadout { public static class LoadoutStore { public const string SelectedHeroKey="PW.SelectedHero"; public const string SelectedWeaponKey="PW.SelectedWeaponKind"; public static int Coins=>PlayerPrefs.GetInt("PW.StoreCoins",500); public static void EnsureDefaults(){if(!PlayerPrefs.HasKey("PW.HeroOwned.0"))PlayerPrefs.SetInt("PW.HeroOwned.0",1);if(!PlayerPrefs.HasKey("PW.WeaponOwned.1"))PlayerPrefs.SetInt("PW.WeaponOwned.1",1);if(!PlayerPrefs.HasKey(SelectedHeroKey))PlayerPrefs.SetInt(SelectedHeroKey,0);if(!PlayerPrefs.HasKey(SelectedWeaponKey))PlayerPrefs.SetInt(SelectedWeaponKey,1);PlayerPrefs.Save();} public static bool IsHeroOwned(int i)=>i==0||PlayerPrefs.GetInt("PW.HeroOwned."+i,0)!=0; public static bool CanUseHero(int i,bool rescued){if(LoadoutTestSwitch.UnlockEverything)return true;return i==0||IsHeroOwned(i)||(i==1&&rescued);} public static bool TryBuyHero(int i,bool rescued){if(i<0||i>=HeroCatalog.Names.Length)return false;if(LoadoutTestSwitch.UnlockEverything||CanUseHero(i,rescued))return true;int p=HeroCatalog.Price(i);if(Coins<p)return false;PlayerPrefs.SetInt("PW.StoreCoins",Coins-p);PlayerPrefs.SetInt("PW.HeroOwned."+i,1);PlayerPrefs.Save();return true;} public static bool IsStageUnlocked(int s)=>s<=0||PlayerPrefs.GetInt("PW.StageCompleted."+s,0)!=0; public static bool IsWeaponOwned(WeaponController.WeaponKind k)=>k==WeaponController.WeaponKind.AssaultRifle||PlayerPrefs.GetInt("PW.WeaponOwned."+(int)k,0)!=0; public static bool CanUseWeapon(WeaponController.WeaponKind k){if(LoadoutTestSwitch.UnlockEverything)return true;var e=WeaponCatalog.Get(k);return IsStageUnlocked(e.RequiredCompletedStage)&&IsWeaponOwned(k);} public static bool TryBuyWeapon(WeaponController.WeaponKind k){if(LoadoutTestSwitch.UnlockEverything||CanUseWeapon(k))return true;var e=WeaponCatalog.Get(k);if(!IsStageUnlocked(e.RequiredCompletedStage)||Coins<e.Price)return false;PlayerPrefs.SetInt("PW.StoreCoins",Coins-e.Price);PlayerPrefs.SetInt("PW.WeaponOwned."+(int)k,1);if(k==WeaponController.WeaponKind.VoidRifle)PlayerPrefs.SetInt("PW.Reward.VoidRifle",1);if(k==WeaponController.WeaponKind.AlienSword)PlayerPrefs.SetInt("PW.Reward.AlienSword",1);PlayerPrefs.Save();return true;} public static int MarkStageCompleted(int stage,bool test){if(test||stage<1||stage>4)return 0;string key="PW.StageCompleted."+stage;bool repeat=PlayerPrefs.GetInt(key,0)!=0;PlayerPrefs.SetInt(key,1);if(stage==3)PlayerPrefs.SetInt("PW.Stage3Unlocked",1);if(stage==4)PlayerPrefs.SetInt("PW.Stage4Unlocked",1);int reward=repeat?100:250;PlayerPrefs.SetInt("PW.StoreCoins",Coins+reward);PlayerPrefs.Save();return reward;} public static int SelectedHero{get=>PlayerPrefs.GetInt(SelectedHeroKey,0);set{PlayerPrefs.SetInt(SelectedHeroKey,Mathf.Clamp(value,0,5));PlayerPrefs.Save();}} public static WeaponController.WeaponKind SelectedWeapon{get=>(WeaponController.WeaponKind)PlayerPrefs.GetInt(SelectedWeaponKey,1);set{PlayerPrefs.SetInt(SelectedWeaponKey,(int)value);PlayerPrefs.Save();}} } }